DO $review$
DECLARE v jsonb; s public.est_source_review%rowtype; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; qid uuid; p jsonb; pid uuid;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "clean:PSD 127", "old_status": "needs_source_reconstruction", "status": "ready", "question_id": "5959b037-2287-5758-8f60-908197c173e9", "stem": "The pie chart summarizes the favorite fruits of 1,420 students. Approximately how many chose mango, and how many more chose apple than oranges?", "choices": [{"key": "A", "text": "250 chose mango; 110 more chose apple than oranges"}, {"key": "B", "text": "250 chose mango; 118 more chose apple than oranges"}, {"key": "C", "text": "306 chose mango; 63 more chose apple than oranges"}, {"key": "D", "text": "187 chose mango; 56 more chose apple than oranges"}], "type": "mcq", "correct": "B", "explanation": "The color legend identifies mango as 17.6%, apple as 21.5%, and oranges as 13.2%. Mango: 1420·0.176=249.92≈250. Apple minus oranges: 1420(0.215−0.132)=117.86≈118.", "topic": "Statistics, Probability & Data Analysis", "verification_source": "New exams_251110_.pdf, physical page 138", "note": "Complete original exam page 138 visually checked; answer independently solved and all choices checked. ", "assets": {"figure": "data:image/jpeg;base64,"}}, {"id": "clean:PSD 134", "old_status": "worked_missing_choice", "status": "ready", "question_id": "e617e251-f121-563a-b5ae-bc60b9b63141", "stem": "Daily low temperatures (°F) were 17, 22, 21, 18, 22, 28, 17, 21, 26, 38, 31, 26, 19, 26. Which stem-and-leaf plot represents all 14 temperatures? (Key: 2|3 means 23.)", "choices": [{"key": "A", "text": "1|7 9; 2|1 2 6 6 8; 3|1 8"}, {"key": "B", "text": "1|7 7 9; 2|1 1 2 2 6 6 6; 3|1 8"}, {"key": "C", "text": "1|7 7 8 9; 2|1 1 2 2 6 6 6 8; 3|1 8"}, {"key": "D", "text": "1|1 7 8 9; 2|1 1 2 2 6 6 6 8; 3|7 8"}], "type": "mcq", "correct": "C", "explanation": "Sort the data: 17,17,18,19; 21,21,22,22,26,26,26,28; 31,38. Using tens as stems gives the three rows in C. There are 4+8+2=14 leaves.", "topic": "Statistics, Probability & Data Analysis", "verification_source": "New exams_251110_.pdf, physical page 417", "note": "Complete original exam page 417 visually checked; answer independently solved and all choices checked. Complete source adds the clipped 17 and 26. Existing question 614833f0-5d71-f2b2-5a61-fcc45e48f827 asks only for the stem-2 leaves; this original asks for the full plot.", "assets": {}}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Missing source %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action=coalesce(v->>'audit_action','source_review_20260929') AND target_id=s.id) THEN CONTINUE; END IF;
  IF s.review_status<>v->>'old_status' THEN RAISE EXCEPTION 'Source status changed %',s.id; END IF;
  qid=nullif(v->>'question_id','')::uuid;
  IF v->>'status'='ready' AND qid IS NOT NULL AND EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE qid=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_deferred_20260929','source_review',s.id,jsonb_build_object('reason','Active exam','proposed',v));
   CONTINUE;
  END IF;
  SELECT * INTO q FROM public.questions WHERE id=qid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=qid FOR UPDATE;
  IF q.id IS NOT NULL AND v ? 'before' AND
    (q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices' OR
     k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation') THEN
    RAISE EXCEPTION 'Concurrent live question change %',qid;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES(coalesce(v->>'audit_action','source_review_20260929'),'source_review',s.id,
    jsonb_build_object('before_source',to_jsonb(s),'before_question',to_jsonb(q),'before_key',to_jsonb(k),'decision',v-'assets'-'before'));
  IF v->>'status'='ready' THEN
   IF q.id IS NOT NULL AND NOT (v ? 'before') THEN RAISE EXCEPTION 'Unexpected existing target %',qid; END IF;
   IF v->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'choices') c WHERE c->>'key'=v->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid key %',s.id; END IF;
   IF v->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(v->'correct')='array' THEN v->'correct'->0 ELSE v->'correct' END,v->'correct') THEN RAISE EXCEPTION 'Grader rejects %',s.id; END IF;
   a=(coalesce(q.assets,'{}'::jsonb)-'release_hold_reason')||coalesce(v->'assets','{}'::jsonb)||jsonb_build_object(
    'verified_release','2026-09-29-independent-solution-and-source-check','answer_review','2026-09-29-independent-solution-and-source-check',
    'verification_note',v->>'note','source_review_id',s.id,'verification_source',coalesce(v->>'verification_source',s.source_document||' page '||s.source_page));
   IF q.id IS NULL THEN
    a=a||jsonb_build_object('source','reviewed-bank-20260929','source_code',s.source_code,'source_document',s.source_document,'source_page',s.source_page);
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(qid,s.track_id,v->>'topic','medium',v->>'type',v->>'stem',v->'choices',a);
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(qid,v->'correct',v->>'explanation');
   ELSE
    UPDATE public.questions SET topic=v->>'topic',type=v->>'type',stem=v->>'stem',choices=v->'choices',assets=a WHERE id=qid;
    UPDATE public.question_keys SET correct=v->'correct',explanation=v->>'explanation' WHERE question_id=qid;
   END IF;
   FOR p IN SELECT value FROM jsonb_array_elements(coalesce(v->'parts','[]'::jsonb)) LOOP
    pid=(p->>'question_id')::uuid;
    IF EXISTS(SELECT 1 FROM public.questions WHERE id=pid) THEN RAISE EXCEPTION 'Split question already exists %',pid; END IF;
    IF p->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'choices') c WHERE c->>'key'=p->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid split key %',pid; END IF;
    IF p->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(p->'correct')='array' THEN p->'correct'->0 ELSE p->'correct' END,p->'correct') THEN RAISE EXCEPTION 'Invalid split numeric key %',pid; END IF;
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(pid,s.track_id,coalesce(p->>'topic',v->>'topic'),'medium',p->>'type',p->>'stem',p->'choices',coalesce(p->'assets','{}'::jsonb)||jsonb_build_object(
      'source','reviewed-bank-20260929','source_review_id',s.id,'source_code',s.source_code||':'||(p->>'label'),'source_document',s.source_document,'source_page',s.source_page,
      'verified_release','2026-09-29-independent-solution-and-source-check','answer_review','2026-09-29-independent-solution-and-source-check','verification_note',p->>'note'));
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(pid,p->'correct',p->>'explanation');
   END LOOP;
  END IF;
  UPDATE public.est_source_review SET review_status=v->>'status',question_id=coalesce(qid,question_id),
   worked_answer=coalesce(v->'correct',worked_answer),duplicate_of=coalesce(v->>'duplicate_of',duplicate_of),
   review_note='Rechecked 2026-09-29. '||coalesce(v->>'note','')||CASE WHEN v ? 'explanation' THEN E'\nWorked solution: '||(v->>'explanation') ELSE '' END,
   updated_at=now() WHERE id=s.id;
  IF v ? 'parts' THEN UPDATE public.est_source_review SET review_note=review_note||E'\nAdditional separately published questions: '||(SELECT string_agg((partrow.value->>'label')||': '||(partrow.value->>'question_id')||'. '||(partrow.value->>'explanation'),E'\n') FROM jsonb_array_elements(v->'parts') partrow(value)) WHERE id=s.id; END IF;
 END LOOP;
END;
$review$;
SELECT count(*) applied_source_decisions FROM public.audit_log WHERE action='source_review_20260929';
